action = False

LOCKED_STATES = ['generated', 'printed', 'signed_uploaded', 'ministry_accredited', 'handover_ready', 'cancelled']

def clean_text(value):
    if not value:
        return ''
    return str(value).strip()

def duration_label(contract):
    value = contract.x_contract_duration_value or 0
    unit = clean_text(contract.x_contract_duration_unit)
    if not value:
        return ''
    if unit == 'year':
        return str(value) + ' سنة'
    if unit == 'month':
        return str(value) + ' شهر'
    if unit == 'day':
        return str(value) + ' يوم'
    return str(value)

record = records.sudo()[:1]

if not record:
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {'title': 'لا يوجد عقد', 'message': 'افتح سجل عقد أولاً.', 'type': 'warning', 'sticky': False},
